        int len = same ? 1 : 0;
        double score = len / 2.0;
        if (len > maxLen) {
          maxLen = len;
          bestScore = score;
          edit = true;
        } else if (len == maxLen && score > bestScore) {
          bestScore = score;
        } else if (len == maxLen && score == bestScore && len > 0 && edit) {
          bestScore += 0.5;
        }
      }
      dp[r][c] += edit ? bestScore : 0.0;
    }
  }
  double total = 0.0;
  int maxLen = 0;
  bool edit = false;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
