      }
    } else if (op == 'BEGIN') {
      edits.add(op);
    } else if (op == 'COMMIT') {
      commit();
    } else if (op == 'ROLLBACK') {
      rollback();
    } else {
      print('Invalid edit: $op');
    }
  }

