  for (int i = 1; i <= n; i++) {
    dp[i][0] = i;
    for (int j = 1; j <= n; j++) {
      if (input[i - 1] == input[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        int minCost = dp[i - 1][j - 1] + 1;
        if (dp[i - 1][j] < minCost) minCost = dp[i - 1][j];
        if (dp[i][j - 1] < minCost) minCost = dp[i][j - 1];
        dp[i][j] = minCost;
      }
    }
  }
  int minCost = dp[n][n];
  if (minCost == 0) return ["blank"];
  List<String> patterns = [];
  void search(int i, int j, List<int> path) {
    if (i == 0 && j == 0) {
      patterns.add(path.join());
      return;
