    if (i == 0 || j == 0) return;
    if (dp[i][j] == dp[i - 1][j - 1] + 1) {
      path.add('-');
      search(i - 1, j - 1, path);
      path.removeLast();
    }
    if (dp[i - 1][j] < dp[i][j - 1]) {
      search(i - 1, j, path);
    } else {
      search(i, j - 1, path);
    }
  }
  List<int> path = [];
  search(n, n, path);
  List<String> categories = ["blank", "isolated", "speckled", "anchored", "floating"];
  return path.reduce((a, b) {
    int diff = (a[0] - b[0]).abs() + (a[1] - b[1]).abs();
