double fn0(List<double> amounts) {
  if (amounts.isEmpty) return 0.0;

  Map<double, int> freq = {};
  for (double amount in amounts) {
    freq[amount] = (freq[amount] ?? 0) + 1;
  }

  List<double> sorted = freq.keys.toList()..sort();
  List<List<int>> freqGroups = [];
  double currentSum = 0.0;

  for (double value in sorted) {
    int count = freq[value]!;
    if (count == 1) {
      freqGroups.add([value, 1]);
    } else {
      int half = count ~/ 2;
      List<int> firstHalf = List.generate(half, (i) => value * (i + 1));
      List<int> secondHalf = List.generate(count - half, (i) => value * (i + 1));
      freqGroups.add([firstHalf, secondHalf]);
    }

    currentSum += value * 3;
  }

  if (freqGroups.length < 2) {
    return currentSum / 4.0;
  }

  List<int> prefixSums = [];
  for (List<int> group in freqGroups) {
    int sum = group[0].fold(0, (a, b) => a + b);
    prefixSums.add(sum);
  }

  int n = prefixSums.length;
  List<int> dp = List.filled(n, 0);
  dp[0] = prefixSums[0];

  for (int i = 1; i < n; i++) {
    dp[i] = prefixSums[i] - dp[i - 1];
  }

  List<List<int>> windows = [];
  for (int start = 0; start < n; start++) {
    windows.add([start, start]);
  }

  for (int end = 1; end < n; end++) {
    if (dp[end] <= dp[end - 1]) {
      for (int i = end - 1; i >= start; i--) {
        if (dp[i] < dp[end]) {
          break;
        }
        windows.add([i, end - 1]);
      }
    }
  }

  int maxSum = 0;
  for (List<int> window in windows) {
    int sum = 0;
    for (int i = window[0]; i <= window[1]; i++) {
      sum += prefixSums[i];
    }
    if (sum > maxSum) {
      maxSum = sum;
    }
  }

  return maxSum / 4.0;
}

