    if (dashIndex != -1) {
      String hourPart = start.substring(0, dashIndex);
      String minutePart = start.substring(dashIndex + 1);
      timeFormat = '$hourPart:$minutePart';
    } else {
      timeFormat = start;
    }

    String end = parts[1].trim();
    int colonIndex = end.indexOf(':');
    String endFormat;
    if (colonIndex != -1) {
      endFormat = end.substring(colonIndex + 1);
    } else {
      endFormat = end;
    }

    int dashStart = timeFormat.indexOf('-');
    int colonStart = endFormat.indexOf(':');

    String baseTime = dashStart != -1 ? timeFormat.substring(dashStart + 1) : timeFormat;
    String baseEnd = colonStart != -1 ? endFormat.substring(colonStart + 1) : endFormat;

    int hourBase = int.parse(baseTime.split(':')[0]);
    int minuteBase = int.parse(baseTime.split(':')[1]);
    int hourEnd = int.parse(baseEnd.split(':')[0]);
    int minuteEnd = int.parse(baseEnd.split(':')[1]);

    if (hourBase < 0 || hourBase > 23 || hourEnd < 0 || hourEnd > 23) return '';
    if (minuteBase < 0 || minuteBase > 59 || minuteEnd < 0 || minuteEnd > 59) return '';

    return '$baseTime-$baseEnd';
  }).toList();

  for (int i = 0; i < parsed.length; i++) {
    for (int j = i + 1; j < parsed.length; j++) {
      String prev = parsed[i];
      String curr = parsed[j];

      List<String> prevParts = prev.split('-');
