    if (len > longest) longest = len;

    current = passes[l][0] <= passes[m + 1][0]
        ? passes[l][0]
        : passes[m + 1][0];
    int prevEnd = passes[l][1] > passes[m + 1][1]
        ? passes[l][1]
        : passes[m + 1][1];
    if (prevEnd > current) current = prevEnd;
  }

  merge(0, passes.length - 1);
  return longest;
}

