Map<String, int> fn0(String input) {
  final result = <String, int>{};
  var state = 0;
  double balance = 0.0;
  String? note;
  for (final token in input.split(' ')) {
    if (token.trim().isEmpty) {
      state = 0;
      balance = 0.0;
      note = null;
      continue;
    }
    final trimmed = token.trim();
    if (state == 0) {
      if (trimmed.length == 3) {
        final digits = trimmed.codeUnits;
        if (digits[0] >= 48 && digits[0] <= 57 &&
            digits[1] >= 48 && digits[1] <= 57 &&
            digits[2] >= 48 && digits[2] <= 57) {
          balance = (balance * 10 + digits[0] - 48) +
              (balance * 10 + digits[1] - 48) +
              (balance * 10 + digits[2] - 48);
          state = 1;
        } else {
          throw FormatException('Invalid banknote');
        }
      } else {
        throw FormatException('Invalid banknote');
      }
    } else if (state == 1) {
      if (trimmed == '*') {
        state = 2;
      } else {
        throw FormatException('Invalid banknote');
      }
    } else if (state == 2) {
      if (trimmed.isEmpty) {
        state = 0;
        balance = 0.0;
        note = null;
      } else {
        if (trimmed.length > 3) {
          throw FormatException('Invalid checksum');
        }
        final digits = trimmed.codeUnits;
        final checksumDigit = digits[0];
        for (int i = 1; i < 3; i++) {
          if (digits[i] < 48 || digits[i] > 57) {
            throw FormatException('Invalid checksum');
          }
        }
        final expected = (100 - (checksumDigit + balance) % 100) % 10;
        if (digits[2] == expected) {
          note = trimmed;
          result[note!] = (result[note] ?? 0) + 1;
        } else {
          throw FormatException('Invalid checksum');
        }
      }
    }
  }
  return result;
}

