Map<String, int> fn0(String ledger, double threshold) {
  final Map<String, int> result = {};
  String category = '';
  double balance = 0.0;

  for (final String entry in ledger.split('\n')) {
    final String trimmed = entry.trim();
    if (trimmed.isEmpty) continue;

    final List<String> parts = trimmed.split(':');
    if (parts.length != 3) continue;

    final String categoryName = parts[0].trim();
    if (categoryName.isEmpty) continue;

    final String amountStr = parts[1].trim();
    if (amountStr.isEmpty) continue;

    double amount;
    try {
      amount = double.parse(amountStr);
    } catch (_) {
      continue;
    }

    if (amount <= threshold) {
      if (categoryName != category) {
        result['$category'] = (result[$category] ?? 0) - balance;
        category = categoryName;
        balance = amount;
      } else {
        balance += amount;
      }
    } else {
      if (categoryName == category) {
        balance += amount - threshold;
      } else {
        result['$category'] = (result[$category] ?? 0) + balance;
        category = categoryName;
        balance = amount;
      }
    }
  }

  result['$category'] = (result[$category] ?? 0) + balance;
  return result;
}

