    if (category == 'H') {
      level = value;
    } else if (category == 'L' && value >= 3) {
      peaks++;
    } else if (category == 'S') {
      if (value <= 0) {
        invalid++;
      } else if (level > 0 && value < level) {
        peaks++;
      }
    }
  }
  return {'level': level, 'peaks': peaks, 'invalid': invalid};
}

