    }
  }
  final Set<int> winners = <int>{};
  int seed = 1;
  for (int round = 1; round <= teamCount; round++) {
    final List<int> nextSeed = <int>[];
    int empty = n;
    while (empty > 0) {
      int slot = empty;
      if (nextSeed.isNotEmpty) {
        slot = nextSeed.removeLast();
      }
      nextSeed.add(slot);
      empty -= 1;
    }
    for (int k = 0; k < nextSeed.length; k++) {
      seed = nextSeed[k];
      int total = 0;
      for (int p = 0; p < bracket.length; p++) {
        if (bracket[p][k] != 0) continue;
        total += seed;
      }
