  if (startRow < 0 || startRow >= rows || startCol < 0 || startCol >= cols) {
    return List<int>.filled(1, -1);
  }

  List<int> distances = List<int>.filled(1, -1);
  Set<String> visited = {};
  bool hasExit = false;

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      String cell = grid[r * 10 + c];
      if (cell == '#') {
        break;
      }
      if (cell == '.' || cell == '/') {
        visited.add(cell);
      }
      if (r == startRow && c == startCol) {
        if (cell == 'T' || cell == 'F') {
          hasExit = true;
        }
        continue;
      }
      if (cell == 'R' || cell == 'S') {
        distances[0] = r * cols + c;
        continue;
      }
      if (r == 0 && c == 0) {
        if (cell == 'U' || cell == 'M') {
          distances[0] = 0;
        }
        continue;
      }

      int dr = 0, dc = 0;
      if (direction == 'U') {
        dr = -1;
        dc = 0;
      } else if (direction == 'D') {
        dr = 1;
        dc = 0;
      } else if (direction == 'L') {
        dr = 0;
        dc = -1;
      } else if (direction == 'R') {
        dr = 0;
        dc = 1;
      }

      if (dr == 0 && dc == 0) {
        continue;
      }

      int nr = r + dr;
      int nc = c + dc;
      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
        continue;
      }

      String neighbor = grid[nr * 10 + nc];
      if (visited.contains(neighbor)) {
        continue;
      }

      visited.add(neighbor);
      if (neighbor == '.' || neighbor == '/') {
        distances[1] = r * cols + c;
      } else if (neighbor == 'R' || neighbor == 'S') {
        distances[0] = r * cols + c;
      } else if (neighbor == 'T' || neighbor == 'F') {
        hasExit = true;
      }
    }
  }

  List<int> result = [];
  for (int i = 0; i < distances.length; i++) {
    if (distances[i] != -1) {
      result.add(distances[i]);
    }
  }

  if (!hasExit) {
    result.add(-1);
  }
  return result;
}

