Set<int> fn0(String log) {
  final errors = <int>{};
  final temperatures = <int>{};
  final readTimes = <int>{};
  final readHeights = <int>{};
  final occupied = <int>{};
  final unstable = <int>{};
  final validDirections = {'N', 'S', 'E', 'W', 'F', 'T', 'R', 'M', 'U', 'W'};

  for (final entry in log.split(',')) {
    final parts = entry.trim().split(':');
    if (parts.length != 3) continue;
    final time = int.tryParse(parts[1]);
    final height = int.tryParse(parts[2]);
    if (time == null || height == null) continue;
    final timestamp = time * 1000;
    final check = parts[0];

    if (check.isEmpty) {
      errors.add(timestamp);
      continue;
    }

    final isValid = <bool>{};
    for (final ch in check.split('')) {
      if (validDirections.contains(ch)) {
        isValid.add(true);
      } else if (ch == 'S' || ch == 'T') {
        isValid.add(height == null);
      } else {
        isValid.add(false);
      }
    }

    if (!isValid.contains(true)) {
      errors.add(timestamp);
      continue;
    }

    if (ch == 'F' && height == 0) {
      unstable.add(timestamp);
      continue;
    }

    for (final dir in check.split('')) {
      if (dir == 'R') {
        readTimes.add(timestamp);
        readHeights.add(height);
        break;
      }
      if (dir != dir.split('').reversed.join()) {
        errors.add(timestamp);
        continue;
      }
      if (dir == 'W') {
        occupied.add(timestamp);
        break;
      }
    }
  }

  for (int i = 0; i < readTimes.length; i++) {
    for (int j = i + 1; j < readTimes.length; j++) {
      if (readHeights[i] == readHeights[j]) {
        errors.add(readTimes[i]);
        errors.add(readTimes[j]);
      }
    }
  }

  for (int h = 0; h < 100; h++) {
    if (occupied.contains(h) && unstable.contains(h)) {
      errors.add(h);
    }
  }

  return errors;
}

