      minDur = sortedWindows[i-1][1] - sortedWindows[i-1][0];
    }
    if (sortedWindows[i][1] - sortedWindows[i-1][1] > maxDur) {
      maxDur = sortedWindows[i-1][1] - sortedWindows[i-1][0];
    }
  }
  return {'windowIndex': sortedWindows[0][1], 'minute': sortedWindows[0][0] + minDur};
}

